1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const DIVERSITY_THRESHOLD = 3;
7	const POINTS_PER_SPHINX = 1;
8	const POINTS_PER_SPHINX_WHEN_DIVERSE = 2;
9	
10	const countSphinxes = (army: Card[]): number =>
11	  army.filter((card) => card.monster === "sphinx").length;
12	
13	// A monster type is its name plus its rank: Undead Warriors of different
14	// ranks are different types, while same-rank ones are the same type.
15	const monsterTypeOf = (card: Card): string => `${card.monster}-${card.rank}`;
16	
17	const countDistinctTypes = (army: Card[]): number =>
18	  new Set(army.map(monsterTypeOf)).size;
19	
20	export const scoreArmy = (army: Card[]): number => {
21	  const isDiverse = countDistinctTypes(army) > DIVERSITY_THRESHOLD;
22	  const pointsPerSphinx = isDiverse ? POINTS_PER_SPHINX_WHEN_DIVERSE : POINTS_PER_SPHINX;
23	  return countSphinxes(army) * pointsPerSphinx;
24	};
